mapper.update:
UPDATE count_line SET recovery_attempts=recovery_attempts+1, recovery_epoch=recovery_epoch+1,
    recovery_lease_until=#{leaseUntil}
WHERE enterprise_id=#{enterpriseId} AND warehouse_id=#{warehouseId} AND id=#{lineId}
  AND recovery_epoch=#{epoch} AND recovery_attempts < 8
  AND status IN ('OBSERVED','RESERVATION_CONFLICT')

UPDATE count_line SET recovery_lease_until=NULL, recovery_next_at=#{nextAt},
    recovery_error_code=#{errorCode}
WHERE enterprise_id=#{enterpriseId} AND warehouse_id=#{warehouseId} AND id=#{lineId}
  AND recovery_epoch=#{epoch} AND status IN ('OBSERVED','RESERVATION_CONFLICT')

mapper.select:
SELECT id, status, reason_code, scope_version, approved_by, approval_id, version
FROM count_plan
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{planId} FOR UPDATE

SELECT id, status, reason_code, scope_version, approved_by, approval_id, version
FROM count_plan
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{planId}

SELECT id, status, reason_code, scope_version, approved_by, approval_id, version, created_at
FROM count_plan
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}

    AND (created_at < #{page.time} OR (created_at = #{page.time} AND id < #{page.id}))

ORDER BY created_at DESC, id DESC
LIMIT #{page.fetchLimit}

mapper.update:
UPDATE count_plan
SET status=#{toStatus}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{planId}
AND status=#{fromStatus}

UPDATE count_plan
SET status='APPROVED', approved_by=#{actor}, approved_at=#{now}, approval_id=#{approvalId}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{planId}
AND status='REVIEWING'

mapper.select:
SELECT location_id, gate_epoch
FROM count_scope
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND count_plan_id=#{planId}
ORDER BY location_id

mapper.update:
UPDATE location_gate
SET state=#{toState}, count_plan_id=#{planId}, reason_code=#{reason}, fence_epoch=fence_epoch+#{epochDelta}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND location_id=#{locationId}
AND state=#{fromState}
AND (count_plan_id IS NULL OR count_plan_id=#{planId})

UPDATE location_gate
SET state='OPEN', count_plan_id=NULL, reason_code=NULL, fence_epoch=fence_epoch+1, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND location_id=#{locationId}
AND state='FROZEN'
AND count_plan_id=#{planId}

mapper.select:
SELECT id, location_id, sku_id, lot_id, quality_code, on_hand_qty, reserved_qty, free_execution_claim_qty, version
FROM stock_balance
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND location_id=#{locationId}
ORDER BY id

SELECT COUNT(*)
FROM stock_balance
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND location_id=#{locationId}
AND free_execution_claim_qty>0

SELECT COUNT(*)
FROM execution_permit p JOIN execution_claim c ON c.enterprise_id=p.enterprise_id
AND c.warehouse_id=p.warehouse_id
AND c.permit_id=p.permit_id JOIN stock_balance b ON b.enterprise_id=c.enterprise_id
AND b.warehouse_id=c.warehouse_id
AND b.id=c.balance_id
WHERE p.enterprise_id=#{enterpriseId}
AND p.warehouse_id=#{warehouseId}
AND b.location_id=#{locationId}
AND p.state IN ('STARTED','UNKNOWN')

SELECT id, balance_id, location_id, snapshot_version, snapshot_qty, reserved_qty, counted_qty, status, version,
    recovery_epoch, recovery_attempts, recovery_error_code
FROM count_line
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND count_plan_id=#{planId}
AND id=#{lineId} FOR UPDATE

SELECT id, balance_id, location_id, snapshot_version, snapshot_qty, reserved_qty, counted_qty, status, version,
    recovery_epoch, recovery_attempts, recovery_error_code
FROM count_line
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND count_plan_id=#{planId}
ORDER BY id

