WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{lineId}

UPDATE count_line
SET status=#{status}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{lineId}
AND status=#{fromStatus}

mapper.select:
SELECT observation_id, count_plan_id, count_line_id, qty, actor_id, round_no, observation_kind, serial_input_json
FROM count_observation
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND observation_id=#{observationId} FOR UPDATE

SELECT COUNT(*)
FROM count_observation
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND count_line_id=#{lineId}

mapper.update:
UPDATE count_scope
SET gate_epoch=#{epoch}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND count_plan_id=#{planId}
AND location_id=#{locationId}

mapper.select:
SELECT gate_epoch
FROM count_scope
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND count_plan_id=#{planId}
AND location_id=#{locationId}

SELECT normalized_serial, presence_code
FROM count_observation_serial
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND observation_id=#{observationId}
ORDER BY normalized_serial

SELECT COUNT(*)
FROM count_observation_serial s JOIN count_observation o ON o.enterprise_id=s.enterprise_id
AND o.warehouse_id=s.warehouse_id
AND o.observation_id=s.observation_id
WHERE o.enterprise_id=#{enterpriseId}
AND o.warehouse_id=#{warehouseId}
AND o.count_line_id=#{lineId}

SELECT observation_id
FROM count_observation
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND count_line_id=#{lineId}
ORDER BY round_no DESC, created_at DESC, id DESC
LIMIT 1
